package org.apache.commons.lang3.math;

import java.io.*;
import java.lang.reflect.Array;
import java.math.*;
import java.math.BigDecimal;
import java.math.BigInteger;
import java.util.*;
import org.apache.commons.lang3.StringUtils;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class NumberUtils_createNumber_TriageGen1Test {





    @Test
    public void testCreateNumber_HexInteger() throws NumberFormatException {
        assertTrue(NumberUtils.createNumber("0x123") instanceof Integer);
        assertTrue(NumberUtils.createNumber("0X12345678") instanceof Integer);
        assertTrue(NumberUtils.createNumber("0x123456789") instanceof Long);
        assertTrue(NumberUtils.createNumber("-0x1234567890123456") instanceof Long);
        assertTrue(NumberUtils.createNumber("#12345678901234567890") instanceof BigInteger);
        assertTrue(NumberUtils.createNumber("-#12345678901234567890") instanceof BigInteger);
    }


















}

