package org.apache.commons.lang3.math;

import java.io.*;
import java.lang.reflect.Array;
import java.math.*;
import java.math.BigDecimal;
import java.math.BigInteger;
import java.util.*;
import org.apache.commons.lang3.StringUtils;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class NumberUtils_createNumber_TriageGen1Test {









    @Test
    public void testCreateNumber_FloatDoubleBigDecimal() throws NumberFormatException {
        assertTrue(NumberUtils.createNumber("123.45") instanceof BigDecimal);
        assertTrue(NumberUtils.createNumber("1.23e2") instanceof Double);
        assertTrue(NumberUtils.createNumber("1.23E2") instanceof Double);
        // Test precision requirement: if float loses precision, it should fall through to Double or BigDecimal
        // 1.00000000000000000001 is too precise for float
        assertTrue(NumberUtils.createNumber("1.00000000000000000001") instanceof BigDecimal);
    }














}

package org.apache.commons.lang3.math;

import java.io.*;
import java.lang.reflect.Array;
import java.math.*;
import java.math.BigDecimal;
import java.math.BigInteger;
import java.util.*;
import org.apache.commons.lang3.StringUtils;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class NumberUtils_createNumber_TriageGen1Test {











    @Test
    public void testCreateNumber_SuffixL() throws NumberFormatException {
        assertTrue(NumberUtils.createNumber("123L") instanceof Long);
        assertTrue(NumberUtils.createNumber("123l") instanceof Long);
        assertTrue(NumberUtils.createNumber("-123L") instanceof Long);
        // BigInteger case for L
        assertTrue(NumberUtils.createNumber("9223372036854775808L") instanceof BigInteger);

        // Invalid L cases
        try {
            NumberUtils.createNumber("123.45L");
            fail("Should throw NFE");
        } catch (NumberFormatException e) {}
    }












}

