package org.apache.commons.lang3.math;

import java.io.*;
import java.lang.reflect.Array;
import java.math.*;
import java.math.BigDecimal;
import java.math.BigInteger;
import java.util.*;
import org.apache.commons.lang3.StringUtils;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class NumberUtils_createNumber_TriageGen1Test {



















    @Test
    public void testCreateNumber_AllZerosLogic() throws NumberFormatException {
        // Test the allZeros logic used for precision checks
        // "0.000" should be treated as 0.0 (float/double) rather than forcing BigDecimal if possible
        assertTrue(NumberUtils.createNumber("0.0") instanceof Float || NumberUtils.createNumber("0.0") instanceof Double);

        // If it's not all zeros but float value is 0, it should fall through to BigDecimal
        // e.g., "0.0000000000000000000000000000000000001"
        assertTrue(NumberUtils.createNumber("0.0000000000000000000000000000000000001") instanceof BigDecimal);
    }




}

